export function getRecommendedForDept(univName, deptName) {
  if (!univName) return null;
  const cleanU = String(univName).trim();
  let univData = UNIV_RECOMMENDED_2028[cleanU];
  if (!univData) {
    const found = Object.keys(UNIV_RECOMMENDED_2028).find(k => k.includes(cleanU) || cleanU.includes(k.split("(")[0].trim()));
    if (found) univData = UNIV_RECOMMENDED_2028[found];
  }
  if (!univData) return null;
  if (!deptName) return univData;
  
  const cleanD = String(deptName).replace(/^[\s└📂]+/, "").trim();
  // 정확 일치
  let matches = univData.filter(m => m.dept === cleanD);
  if (matches.length > 0) return matches;
  // 부분 일치
  const cleanCore = cleanD.replace(/학과|학부|과$|전공|학|계열|대학/g, "");
  if (cleanCore.length > 1) {
    matches = univData.filter(m => {
      const mDept = m.dept.replace(/학과|학부|과$|전공|학|계열|대학/g, "");
      return mDept.includes(cleanCore) || cleanCore.includes(mDept);
    });
    if (matches.length > 0) return matches;
  }
  // 단과대학으로 부분 매칭
  matches = univData.filter(m => m.college && (m.college.includes(cleanCore) || cleanD.includes(m.college)));
  if (matches.length > 0) return matches.slice(0, 3);
  return null;
}

export const UNIV_NAMES_2028 = Object.keys(UNIV_RECOMMENDED_2028).sort();

// 학과명 자동완성용 — 모든 대학의 학과 목록 집합
export const ALL_DEPTS_2028 = (function() {
  const set = new Set();
  Object.values(UNIV_RECOMMENDED_2028).forEach(arr => {
    arr.forEach(m => { if (m.dept) set.add(m.dept); });
  });
  return Array.from(set).sort();
})();

