// 학과명으로 계열 정보 조회
export function getSeriesInfo(deptName) {
  if (!deptName) return null;
  const clean = String(deptName).replace(/^[\s└📂]+/, "").trim();
  // 정확 매칭
  if (DEPT_TO_SERIES[clean]) {
    const [series, unit] = DEPT_TO_SERIES[clean];
    return {series, unit, subjects: SERIES_RECOMMENDED_2028[series]?.[unit] || null};
  }
  // 부분 매칭
  for (const [key, val] of Object.entries(DEPT_TO_SERIES)) {
    if (clean.includes(key)) {
      const [series, unit] = val;
      return {series, unit, subjects: SERIES_RECOMMENDED_2028[series]?.[unit] || null};
    }
  }
  return null;
}

// ════════════════════════════════════════════════════════
// 🆕 통합 자유검색 인덱스 (방안 A)
// 대학+모집단위를 한 배열로 평탄화 → 자유 검색용
// ════════════════════════════════════════════════════════
export const SEARCH_INDEX_2028 = (function () {
  const out = [];
  const seen = new Set();
  for (const [univ, items] of Object.entries(UNIV_RECOMMENDED_2028)) {
    // 대학명 정리 (괄호 캠퍼스 표기 유지)
    for (const it of items) {
      if (!it.dept) continue;
      const key = univ + "|" + it.dept;
      if (seen.has(key)) continue;
      seen.add(key);
      out.push({
        univ,
        dept: it.dept,
        college: it.college || "",
        label: `${univ} ${it.dept}`,
        // 검색용 정규화 문자열 (공백 제거, 소문자)
        norm: (univ + it.dept + (it.college || "")).replace(/\s+/g, "").toLowerCase(),
      });
    }
  }
  return out;
})();

// 자유 검색 함수 — 대학명/학과명 일부만 입력해도 매칭
// 🆕 전국 주요 대학 보강 목록 (2028 공식 데이터에 없는 대학 포함)
const EXTRA_UNIVS = [
  "서울대","연세대","고려대","성균관대","서강대","한양대","중앙대","경희대","한국외대","서울시립대","이화여대",
  "건국대","동국대","홍익대","국민대","숭실대","세종대","단국대","서울과기대","광운대","명지대","상명대","숙명여대","덕성여대","성신여대","동덕여대","가톨릭대","아주대","인하대","가천대","경기대","한국항공대",
  "부산대","경북대","전남대","전북대","충남대","충북대","강원대","경상국립대","제주대","공주대","순천향대","인천대",
  "KAIST","POSTECH","DGIST","GIST","UNIST","한국에너지공대",
  "교대","사관학교","경찰대","간호대",
];
const COMMON_DEPTS = [
  "경영학과","경제학과","국어국문학과","영어영문학과","사학과","철학과","심리학과","사회학과","정치외교학과","행정학과","법학과","미디어커뮤니케이션학과","교육학과",
  "수학과","물리학과","화학과","생명과학과","컴퓨터공학과","전자공학과","기계공학과","화학공학과","건축학과","산업공학과","신소재공학과","간호학과","의예과","약학과","수의예과",
  "국어교육과","영어교육과","수학교육과","역사교육과","체육교육과","유아교육과","초등교육과",
];
const EXTRA_INDEX = (function(){
  const out=[];
  const officialUnivs=new Set(SEARCH_INDEX_2028.map(x=>x.univ));
  for(const u of EXTRA_UNIVS){
    // 2028 공식에 이미 있는 대학은 학과가 충분하므로 대학명만 보조 등록
    for(const d of COMMON_DEPTS){
      out.push({univ:u,dept:d,college:"",label:`${u} ${d}`,norm:(u+d).replace(/\s+/g,"").toLowerCase(),extra:true});
    }
  }
  return out;
})();

export function searchUnivDept(query, limit = 20) {
  if (!query || query.trim().length === 0) return [];
  // 약칭 → 정식 표기 치환
  const ALIAS = {"카이스트":"KAIST","케이스트":"KAIST","포스텍":"POSTECH","포항공대":"POSTECH","유니스트":"UNIST","지스트":"GIST","디지스트":"DGIST"};
  let qraw = query.trim();
  for(const [k,v] of Object.entries(ALIAS)){ if(qraw.includes(k)) qraw = qraw.replace(k,v); }
  const q = qraw.replace(/\s+/g, "").toLowerCase();
  const terms = qraw.split(/\s+/).map(t => t.toLowerCase()).filter(Boolean);

  const scoreItem = (item, isExtra) => {
    let score = 0;
    if (item.norm.includes(q)) score += 100;
    let allTermsMatch = true;
    for (const t of terms) {
      const inUniv = item.univ.toLowerCase().includes(t);
      const inDept = item.dept.toLowerCase().includes(t);
      const inCollege = (item.college||"").toLowerCase().includes(t);
      if (inUniv) score += 30;
      else if (inDept) score += 25;
      else if (inCollege) score += 15;
      else { allTermsMatch = false; }
    }
    if (!allTermsMatch || score <= 0) return null;
    if (terms.length && item.univ.toLowerCase().startsWith(terms[0])) score += 20;
    // 공식 데이터 우선 (보강 인덱스는 약간 감점)
    if (isExtra) score -= 8;
    return score;
  };

  const scored = [];
  for (const item of SEARCH_INDEX_2028) {
    const sc = scoreItem(item, false);
    if (sc !== null) scored.push({ ...item, score: sc });
  }
  // 공식 결과가 부족하면 보강 인덱스도 추가
  for (const item of EXTRA_INDEX) {
    const sc = scoreItem(item, true);
    if (sc !== null) scored.push({ ...item, score: sc });
  }
  // 중복 제거 (label 기준, 높은 점수 우선)
  scored.sort((a, b) => b.score - a.score || a.label.length - b.label.length);
  const seen = new Set();
  const dedup = [];
  for (const s of scored) {
    if (seen.has(s.label)) continue;
    seen.add(s.label);
    dedup.push(s);
  }
  return dedup.slice(0, limit);
}
